//! 🧪️ Provenance text copies and every abandoned partial cursor have exact physical receipts.
use super::*;
use semio_framework_os_kernel::MutationOrigin;
use semio_framework_os_kernel as store;
use semio_framework_job::{OriginalJobFixtureCaller,OriginalJobDecodeOwner,OperationId,Generation,default_now_us};
use semio_framework_value::RetainedCloneGrant;
fn turn<R>(caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,g:RetainedCloneGrant,run:impl FnOnce(&mut StepContext<'_>)->Result<R,OriginalTurnFailure>)->R{let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn_with_decoder(g,decoder,run));let p=caller.receipt();assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes),"actual original provenance receipt {p:?}");result.unwrap()}
#[test]fn original_provenance_copies_preserve_all_variants_and_close_every_cancelled_cursor(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();let count=law["count"].as_u64().unwrap()as usize;
 for kind in 0..3{for cut in law["cancelPrefixes"].as_array().unwrap().iter().map(|n|Some(n.as_u64().unwrap()as usize)).chain([None]){
  let original=match kind{0=>MutationOrigin::Owner,1=>MutationOrigin::Contributed{plugin_id:law["pluginId"].as_str().unwrap().repeat(law["repeat"].as_u64().unwrap()as usize),mutation_id:store::SchemaId(law["mutationId"].as_str().unwrap().into()),payload_hash:store::PayloadHash([7;32])},_=>MutationOrigin::Transaction{initiator:store::ForeignTarget{artifact_id:law["initiator"]["artifactId"].as_str().unwrap().into(),artifact_kind:law["initiator"]["artifactKind"].as_str().unwrap().into(),dialect:Some(law["initiator"]["dialect"].as_str().unwrap().into())}}};let oracle=original.clone();let mut original=Some(original);
  let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:1<<24,maximum_release_bytes:1<<24,maximum_depth:4096};let mut caller=OriginalJobFixtureCaller::admit(OperationId(382),Generation(8),RetainedCloneGrant{maximum_items:1<<30,maximum_copy_bytes:1<<30,maximum_capacity_bytes:1<<29,maximum_release_bytes:1<<29,maximum_depth:4096},default_now_us,u64::MAX,1<<30);let mut decoder=OriginalJobDecodeOwner::empty();let mut owner=None;
  turn(&mut caller,&mut decoder,g,|cx|{assert!(OriginalValueCopies::<MutationOrigin>::admit(&mut original,count,cx,&mut owner)?);Ok(())});assert!(original.is_none());
  for index in 0..262144{if cut==Some(index){break}let ready=turn(&mut caller,&mut decoder,g,|cx|owner.as_mut().unwrap().advance(cx));if ready{break}assert!(index<262143,"original provenance did not settle");}
  let mut output=None;if cut.is_none(){turn(&mut caller,&mut decoder,g,|cx|{assert!(owner.as_mut().unwrap().take(cx,&mut output)?);Ok(())});let rows=output.as_ref().unwrap();assert_eq!(rows.len(),count);for row in rows{assert_eq!(row,&oracle);}if let MutationOrigin::Contributed{plugin_id:source,..}=&oracle{for row in rows{let MutationOrigin::Contributed{plugin_id,..}=row else{unreachable!()};assert_ne!(source.as_ptr(),plugin_id.as_ptr());assert_eq!(serde_json::from_str::<String>(&serde_json::to_string(plugin_id).unwrap()).unwrap(),law["pluginId"].as_str().unwrap().repeat(law["repeat"].as_u64().unwrap()as usize));}}}else{caller.cancel().cancel_now();}
  for index in 0..262144{if owner.as_ref().unwrap().terminal_is_empty(){break}turn(&mut caller,&mut decoder,g,|cx|cx.with_original_retirement(|cx|owner.as_mut().unwrap().close_step(cx)));assert!(index<262143,"original provenance cancellation did not settle");}
  turn(&mut caller,&mut decoder,g,|cx|cx.with_original_retirement(|cx|{let d=OriginalValueCopies::<MutationOrigin>::release_demands();close_original_retained_step(cx,d,|_|{owner.take();Ok(RetainedCloneStep::Complete(receipt(d)))})?;Ok(())}));
  if output.is_some(){let mut retirement=RetainedCloneClose::default();for index in 0..262144{if output.is_none()&&retirement.is_empty(){break}turn(&mut caller,&mut decoder,g,|cx|cx.with_original_retirement(|cx|{let d=retirement.next_owner_demands::<VecDeque<MutationOrigin>>(output.is_some(),&None,4096)?;close_original_retained_step(cx,d,|grant|if retirement.is_empty(){Ok(retirement.begin_granted(&mut output,grant)?.unwrap_or(RetainedCloneStep::Complete(Default::default())))}else{retirement.select(4096)?.step(grant)})?;Ok(())}));assert!(index<262143);}}
  while !decoder.terminal_is_empty(){caller.turn(g,|cx|cx.with_original_retirement(|cx|{let d=decoder.retirement_demands(4096)?;close_original_retained_step(cx,d,|grant|decoder.close_step(grant))?;Ok(())})).unwrap();}caller.retire(g);
 }}
}
